function UIMazeChooseBuffCellNode:Refresh(data, clickCb, selectCb)
    if not data then
        return
    end

    self._data = data
    self._clickCb = clickCb
    self._selectCb = selectCb

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end
    if self._itemLoader.IsSuccess then
        local go = self.head.transform:Find("item")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, self.head)
            go.name = "item"
        end
        if go then
            CfUtils.RefeshGoodGo(go, data.refId, 0, 1, Constants.IDArea.Maze, function()
            end)
        end
    end

    CfUtils.FillText(self.name, data.name)
    CfUtils.FillText(self.desc, data.description)

    KTool.SetActive(self.controller.gameObject, true)
end

